create or replace function public.valuation_road_hierarchy_backtest_lo_curro_v1() returns jsonb language sql stable security definer set search_path=public,private,extensions as $$ with base as ( select t.*, ts.elevation_m, ts.slope_degrees, ts.aspect_degrees, ts.relative_elevation_m, ts.roughness_m, rs.hierarchy_rank::numeric road_rank, ln(1+rs.distance_to_road_m)::numeric log_road_distance, ln(1+coalesce(rs.distance_to_arterial_m,700))::numeric log_arterial_distance, (t.built_area_m2 + 0.15*t.land_area_m2)::numeric effective_area, t.price_uf/nullif((t.built_area_m2+0.15*t.land_area_m2),0) effective_rate, coalesce(q.has_extreme_price_conflict,false) extreme_conflict from public.market_cbrs_reference_transactions t join public.valuation_topography_samples ts on round(ts.latitude::numeric,6)=round(t.latitude::numeric,6) and round(ts.longitude::numeric,6)=round(t.longitude::numeric,6) and ts.source_version='copernicus-dem-2021-glo90-open-meteo-90m' join public.valuation_road_hierarchy_samples rs on round(rs.latitude::numeric,6)=round(t.latitude::numeric,6) and round(rs.longitude::numeric,6)=round(t.longitude::numeric,6) and rs.source_version='osm-overpass-v1' left join private.market_cbrs_rol_quality_v1 q on q.rol=t.rol where t.property_type ilike '%casa%' and t.price_uf>0 and t.built_area_m2>0 and t.land_area_m2>0 and t.construction_year is not null and public.valuation_pp_kml_barrio_at(t.latitude,t.longitude)='Lo Curro' ), clean as (select * from base where not extreme_conflict), train as (select * from clean where transaction_date<date '2024-01-01'), test as (select * from clean where transaction_date>=date '2024-01-01' and transaction_date<date '2026-01-01'), sc as ( select greatest(percentile_cont(.75) within group(order by ln(built_area_m2))-percentile_cont(.25) within group(order by ln(built_area_m2)),.05) sb, greatest(percentile_cont(.75) within group(order by ln(land_area_m2))-percentile_cont(.25) within group(order by ln(land_area_m2)),.05) sl, greatest(percentile_cont(.75) within group(order by construction_year)-percentile_cont(.25) within group(order by construction_year),5) sy, greatest(percentile_cont(.75) within group(order by elevation_m)-percentile_cont(.25) within group(order by elevation_m),20) se, greatest(percentile_cont(.75) within group(order by slope_degrees)-percentile_cont(.25) within group(order by slope_degrees),2) ss, greatest(percentile_cont(.75) within group(order by relative_elevation_m)-percentile_cont(.25) within group(order by relative_elevation_m),2) sr, greatest(percentile_cont(.75) within group(order by roughness_m)-percentile_cont(.25) within group(order by roughness_m),5) sg, greatest(percentile_cont(.75) within group(order by road_rank)-percentile_cont(.25) within group(order by road_rank),1) sh, greatest(percentile_cont(.75) within group(order by log_road_distance)-percentile_cont(.25) within group(order by log_road_distance),.25) sd, greatest(percentile_cont(.75) within group(order by log_arterial_distance)-percentile_cont(.25) within group(order by log_arterial_distance),.25) sa from train ), p as ( select x.*, (select sum(effective_rate*w)/sum(w)*x.effective_area from (select effective_rate,1/(.15+d) w from (select tr.effective_rate, abs(ln(tr.built_area_m2/x.built_area_m2))/sc.sb+abs(ln(tr.land_area_m2/x.land_area_m2))/sc.sl+abs(tr.construction_year-x.construction_year)/sc.sy+extract(year from age(x.transaction_date,tr.transaction_date))/10+abs(tr.elevation_m-x.elevation_m)/sc.se+abs(tr.slope_degrees-x.slope_degrees)/sc.ss+abs(tr.relative_elevation_m-x.relative_elevation_m)/sc.sr+abs(tr.roughness_m-x.roughness_m)/sc.sg+least(abs(tr.aspect_degrees-x.aspect_degrees),360-abs(tr.aspect_degrees-x.aspect_degrees))/90 d from train tr cross join sc where not(round(tr.latitude::numeric,6)=round(x.latitude::numeric,6) and round(tr.longitude::numeric,6)=round(x.longitude::numeric,6))) z order by d limit 8) q) topo_pred, (select sum(effective_rate*w)/sum(w)*x.effective_area from (select effective_rate,1/(.15+d) w from (select tr.effective_rate, abs(ln(tr.built_area_m2/x.built_area_m2))/sc.sb+abs(ln(tr.land_area_m2/x.land_area_m2))/sc.sl+abs(tr.construction_year-x.construction_year)/sc.sy+extract(year from age(x.transaction_date,tr.transaction_date))/10+abs(tr.elevation_m-x.elevation_m)/sc.se+abs(tr.slope_degrees-x.slope_degrees)/sc.ss+abs(tr.relative_elevation_m-x.relative_elevation_m)/sc.sr+abs(tr.roughness_m-x.roughness_m)/sc.sg+least(abs(tr.aspect_degrees-x.aspect_degrees),360-abs(tr.aspect_degrees-x.aspect_degrees))/90+abs(tr.road_rank-x.road_rank)/sc.sh+abs(tr.log_road_distance-x.log_road_distance)/sc.sd+abs(tr.log_arterial_distance-x.log_arterial_distance)/sc.sa d from train tr cross join sc where not(round(tr.latitude::numeric,6)=round(x.latitude::numeric,6) and round(tr.longitude::numeric,6)=round(x.longitude::numeric,6))) z order by d limit 8) q) topo_road_pred from test x ), y as (select extract(year from transaction_date)::int yr,count(*) n,avg(abs(topo_pred-price_uf)/price_uf)*100 topo_mape,avg(abs(topo_road_pred-price_uf)/price_uf)*100 topo_road_mape,avg(abs(topo_pred-price_uf)) topo_mae,avg(abs(topo_road_pred-price_uf)) topo_road_mae,avg(topo_pred-price_uf) topo_bias,avg(topo_road_pred-price_uf) topo_road_bias from p group by 1), a as (select count(*) n,avg(abs(topo_pred-price_uf)/price_uf)*100 topo_mape,avg(abs(topo_road_pred-price_uf)/price_uf)*100 topo_road_mape,avg(abs(topo_pred-price_uf)) topo_mae,avg(abs(topo_road_pred-price_uf)) topo_road_mae,avg(topo_pred-price_uf) topo_bias,avg(topo_road_pred-price_uf) topo_road_bias from p) select jsonb_build_object('status',case when a.n>=20 then 'shadow_evaluation' else 'insufficient_road_coverage' end,'roadSourceVersion','osm-overpass-v1','topographySourceVersion','copernicus-dem-2021-glo90-open-meteo-90m','trainWindow','2014-2023','holdoutWindow','2024-2025','sameLocationLeakageExcluded',true,'extremeRolConflictsExcluded',true,'changesChampionWeights',false,'overall',jsonb_build_object('n',a.n,'topographyMapePct',round(a.topo_mape::numeric,2),'topographyRoadMapePct',round(a.topo_road_mape::numeric,2),'mapeImprovementPp',round((a.topo_mape-a.topo_road_mape)::numeric,2),'topographyMaeUf',round(a.topo_mae::numeric,0),'topographyRoadMaeUf',round(a.topo_road_mae::numeric,0),'topographyBiasUf',round(a.topo_bias::numeric,0),'topographyRoadBiasUf',round(a.topo_road_bias::numeric,0)),'byYear',(select jsonb_agg(jsonb_build_object('year',yr,'n',n,'topographyMapePct',round(topo_mape::numeric,2),'topographyRoadMapePct',round(topo_road_mape::numeric,2),'topographyMaeUf',round(topo_mae::numeric,0),'topographyRoadMaeUf',round(topo_road_mae::numeric,0),'topographyBiasUf',round(topo_bias::numeric,0),'topographyRoadBiasUf',round(topo_road_bias::numeric,0)) order by yr) from y),'decision',case when a.n<20 then 'WAIT_FOR_COVERAGE' when a.topo_road_mape<a.topo_mape*.95 and a.topo_road_mae<a.topo_mae and abs(a.topo_road_bias)<=greatest(abs(a.topo_bias)*1.10,1000) then 'PROMOTE_TO_COMBINED_CHALLENGER' else 'HOLD' end) from a; $$; revoke all on function public.valuation_road_hierarchy_backtest_lo_curro_v1() from public,anon; grant execute on function public.valuation_road_hierarchy_backtest_lo_curro_v1() to authenticated,service_role;